(() => {
  const API_BASE = '';
  const SESSION_STORAGE_KEY = 'pr29_session_token';
  const state = { session: null, content: null, slides: [], products: [], basket: {}, gourmandExtras: {}, slots: [], reservationSlots: [], history: null, overview: null, period: 'day', date: new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Paris', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date()), notice: '', carouselIndex: 0, orderOpen: false, reservationOpen: false, adminLoadToken: 0 };
  const $ = (selector, parent = document) => parent.querySelector(selector);
  const money = (value) => new Intl.NumberFormat('fr-FR', { style: 'currency', currency: 'EUR' }).format(Number(value || 0) / 100);
  const dateLabel = (date, time) => new Intl.DateTimeFormat('fr-FR', { dateStyle: 'medium', timeStyle: time ? 'short' : undefined }).format(new Date(date + (time ? 'T' + time + ':00' : 'T12:00:00')));
  const esc = (value) => String(value == null ? '' : value).replace(/[&<>'"]/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', "'":'&#39;', '"':'&quot;' })[c]);
  const safeUrl = (value) => /^\/media\//.test(value || '') ? API_BASE + value : /^\/carousel\//.test(value || '') || /^https:\/\//.test(value || '') ? value : '';
  const statusNames = {PENDING:'À confirmer',CONFIRMED:'Confirmée',COMPLETED:'Terminée',TO_PREPARE:'À préparer',PREPARING:'En préparation',READY:'Prête au retrait',COLLECTED:'Retirée · payée sur place',CANCELLED:'Annulée'};
  const statusLabel = value => statusNames[value] || value;
  const clockValue = value => String(Math.floor(value/60)).padStart(2,'0')+':'+String(value%60).padStart(2,'0');
  function statusControl(kind,record) {
    if(['COLLECTED','CANCELLED','COMPLETED'].includes(record.status))return '';
    const options=kind==='orders'?['TO_PREPARE','PREPARING','READY','COLLECTED','CANCELLED']:['PENDING','CONFIRMED','COMPLETED','CANCELLED'];
    return '<label>Statut <select data-status-kind="'+kind+'" data-status-id="'+record.id+'">'+options.map(value=>'<option value="'+value+'" '+(record.status===value?'selected':'')+'>'+statusLabel(value)+'</option>').join('')+'</select></label>';
  }
  // Produits créés depuis l'administration sans emplacement prévu : rangés avec les burgers ou les softs.
  const KNOWN_SLUGS = ['le-p-tit-cheese','le-breton','le-chevre-miel','le-poulet-crudites','le-veg','burger-semaine','steak-hache-frites','filet-poulet-fermier','galette-legumes','formule-burger-accompagnement','kids-cheese-frites','kids-nuggets-frites','cafe','double-cafe','the','infusion','eau-plate','eau-gazeuse','cola-artisanal','breizh-cola-zero','sirop-eau','jus-pommes','limonade-bretonne','the-glace-maison','digestif','biere-locale','cidre-local','vin-verre','vin-bouteille'];
  const newProducts = category => state.products.filter(product => product.category === category && !KNOWN_SLUGS.includes(product.slug));
  const categoryNames = { BURGER: 'Burgers, plats & formules', ACCOMPAGNEMENT: 'Accompagnements & p’tits plus', BOISSON: 'Boissons', DESSERT: 'Desserts' };

  async function api(path, options = {}) {
    const headers = new Headers(options.headers || {});
    const sessionToken = API_BASE ? localStorage.getItem(SESSION_STORAGE_KEY) : '';
    if (sessionToken) headers.set('authorization', 'Bearer ' + sessionToken);
    if (options.body && !(options.body instanceof FormData)) headers.set('content-type', 'application/json');
    const response = await fetch(API_BASE + path, { ...options, headers, body: options.body && !(options.body instanceof FormData) ? JSON.stringify(options.body) : options.body });
    const data = response.status === 204 ? {} : await response.json().catch(() => ({}));
    document.querySelectorAll('form[data-pending="true"]').forEach(form=>{delete form.dataset.pending;form.querySelectorAll('button[type="submit"],button:not([type])').forEach(btn=>btn.disabled=false);});
    if (!response.ok) throw new Error(data.error || 'Impossible de terminer cette action.');
    return data;
  }

  function flash(message, type = 'success') {
    state.notice = { message, type };document.querySelectorAll('form[data-pending="true"]').forEach(form=>{delete form.dataset.pending;form.querySelectorAll('button[type="submit"],button:not([type])').forEach(btn=>btn.disabled=false);});
    let toast = $('#feedback'); if (!toast) { toast = document.createElement('div'); toast.id = 'feedback'; toast.setAttribute('role', 'status'); document.body.append(toast); }
    toast.className = 'toast ' + type; toast.textContent = message;
    clearTimeout(state.toastTimer); state.toastTimer = setTimeout(() => toast.remove(), 9000);
  }
  function content() { return state.content || { restaurantName: "Le P'tit Resto 29", town: 'Fouesnant', phone: '02 98 51 06 38', heroEyebrow: 'Fouesnant', heroTitle: 'Du fait maison qui a du caractère.', heroText: '' }; }
  function header() {
    const user = state.session, c = content();
    const accountHref = user ? user.role === 'admin' ? '/admin' : '/compte' : '/connexion';
    const accountLabel = user ? user.role === 'admin' ? 'Administration' : 'Mon compte' : 'Se connecter';
    return '<header class="nav"><div class="wrap navin"><a class="brand" href="/#top"><img class="brandSeal" src="/brand/logo-rond.webp" alt="Logo Le P’tit Resto 29"><span class="brandWordmark">' + esc(c.restaurantName.toUpperCase()) + '<small>' + esc(c.town.toUpperCase()) + '</small></span></a><div class="headerMenus"><details class="headerMenu"><summary aria-label="Ouvrir le menu principal"><span class="burgerIcon" aria-hidden="true"><i></i><i></i><i></i></span><span>Menu</span></summary><nav class="headerMenuPanel" aria-label="Navigation principale"><a href="/#carte">La carte</a><a href="/#resto">Le resto</a><a href="/#commander">Commander</a><a href="/#reservation">Réserver</a></nav></details><details class="headerMenu accountMenu"><summary aria-label="Ouvrir le menu du compte"><span class="accountIcon" aria-hidden="true">●</span><span>Compte</span></summary><div class="headerMenuPanel"><a href="' + accountHref + '">' + accountLabel + '</a>' + (user ? '<button class="logoutButton" data-action="logout">Déconnexion</button>' : '') + '</div></details></div></div></header>';
  }
  function notice() { return state.notice ? '<p class="toast ' + state.notice.type + '" role="status">' + esc(state.notice.message) + '</p>' : ''; }
  function pageShell(body) { return header() + body + '<footer class="legalFooter"><a href="/mentions-legales">Mentions légales et confidentialité</a></footer>'; }
  function carousel() {
    if (!state.slides.length) return '<section id="top" class="burgerCarousel carouselEmpty"><div class="wrap"><p>Burgers de la semaine</p><strong>Les prochaines recettes arrivent bientôt.</strong></div></section>';
    return '<section id="top" class="burgerCarousel" aria-roledescription="carrousel" aria-label="Les burgers de la semaine"><div class="carouselViewport"><div class="carouselTrack">' + state.slides.map((slide,i) => '<article class="carouselSlide" aria-hidden="' + (i!==state.carouselIndex) + '"><img src="' + esc(safeUrl(slide.image)) + '" alt="' + esc(slide.title) + '"><div class="carouselOverlay"></div><div class="wrap carouselCaption"><span class="carouselEyebrow">Burger de la semaine</span><h2>' + esc(slide.title) + '</h2></div></article>').join('') + '</div></div><div class="carouselControls wrap"><button class="carouselArrow" aria-label="Photo précédente" data-action="carousel-prev">←</button><div class="carouselDots">' + state.slides.map((slide,i) => '<button data-slide="' + i + '" aria-label="Afficher ' + esc(slide.title) + '" aria-current="' + (i===state.carouselIndex) + '" class="' + (i===state.carouselIndex?'active':'') + '"></button>').join('') + '</div><button class="carouselArrow" aria-label="Photo suivante" data-action="carousel-next">→</button></div></section>';
  }
  function updateCarousel() {
    const track = $('.carouselTrack'); if (!track) return;
    track.style.transform = 'translateX(-' + state.carouselIndex * 100 + '%)';
    document.querySelectorAll('.carouselSlide').forEach((el,i) => el.setAttribute('aria-hidden', String(i!==state.carouselIndex)));
    document.querySelectorAll('[data-slide]').forEach((el,i) => { el.classList.toggle('active', i===state.carouselIndex); el.setAttribute('aria-current', String(i===state.carouselIndex)); });
  }
  function home() {
    const c = content();
    return pageShell(carousel() + '<main><section class="hero"><div class="wrap heroGrid"><div><div class="eyebrow">' + esc(c.heroEyebrow) + '</div><h1>' + esc(c.heroTitle) + '</h1><p>' + esc(c.heroText) + '</p><div class="heroActions"><a class="btn" href="#carte">Découvrir la carte</a></div></div></div></section>' + menuPreview() + orderSection() + reservationSection() + restaurantSection() + '</main>');
  }
  function menuPreview() {
    const withSlugs = slugs => state.products.filter(product => slugs.includes(product.slug));
    const sections = [
      { id:'burgers', eyebrow:'Les incontournables', title:'Burgers maison', products:withSlugs(['le-p-tit-cheese','le-breton','le-chevre-miel','le-poulet-crudites','le-veg','burger-semaine']).concat(newProducts('BURGER')), burgerOptions:true, note:'* Option Gourmand : ajoutez un supplément de poulet ou de bœuf à votre burger (+3,50 €).' },
      { id:'plats', eyebrow:'À l’assiette', title:'Les plats', products:withSlugs(['steak-hache-frites','filet-poulet-fermier','galette-legumes']) },
      { id:'formules', eyebrow:'Pour les petites et grandes faims', title:'Formules', products:withSlugs(['formule-burger-accompagnement']) },
      { id:'enfants', eyebrow:'Pour les p’tits gourmands', title:'Menu enfant', products:withSlugs(['kids-cheese-frites','kids-nuggets-frites']) },
      { id:'accompagnements', eyebrow:'À partager ou en plus', title:'Accompagnements & p’tits plus', products:state.products.filter(product => product.category === 'ACCOMPAGNEMENT' && product.slug !== 'le-gourmand') },
      { id:'desserts', eyebrow:'La note sucrée', title:'Desserts', products:state.products.filter(product => product.category === 'DESSERT') },
      { id:'chaudes', eyebrow:'Équitable & bio', title:'Boissons chaudes', products:withSlugs(['cafe','double-cafe','the','infusion']) },
      { id:'softs', eyebrow:'Fraîcheur locale', title:'Boissons soft', products:withSlugs(['eau-plate','eau-gazeuse','cola-artisanal','breizh-cola-zero','sirop-eau','jus-pommes','limonade-bretonne','the-glace-maison']).concat(newProducts('BOISSON')) },
      { id:'alcools', eyebrow:'À consommer avec modération', title:'Bières, cidre & vins', products:withSlugs(['digestif','biere-locale','cidre-local','vin-verre','vin-bouteille']) }
    ].filter(section => section.products.length);
    const cards = (products, showOption=false) => products.map(product => '<article class="menuCard"><div><h4>'+esc(product.name)+(showOption?'<sup aria-label="Option Gourmand disponible">*</sup>':'')+'</h4><p>'+esc(product.description)+'</p></div><div class="price">'+money(product.priceCents)+'</div></article>').join('');
    return '<section class="section" id="carte"><div class="wrap menuShowcase"><div class="menuTitleRow"><img class="menuBrandMark" src="/brand/logo-burger.webp" alt=""><div class="section-heading"><p class="eyebrow">La carte</p><h2>La vraie carte du P’tit Resto.</h2><p>Choisissez une famille pour explorer la carte, sans faire défiler une liste interminable.</p></div></div><nav class="menuJump" aria-label="Familles de la carte">'+sections.map(section=>'<button type="button" data-menu-jump="menu-'+section.id+'">'+esc(section.title)+'</button>').join('')+'</nav><div class="menuGroups">'+sections.map((section,index)=>'<details class="menuGroup" id="menu-'+section.id+'" '+(index===0&&!matchMedia('(max-width: 600px)').matches?'open':'')+'><summary><span><small>'+esc(section.eyebrow)+'</small><strong>'+esc(section.title)+'</strong></span><em>'+section.products.length+' choix</em><b aria-hidden="true">+</b></summary><div class="menuGrid">'+cards(section.products,section.burgerOptions)+'</div>'+(section.note?'<p class="menuFootnote">'+esc(section.note)+'</p>':'')+'</details>').join('')+'</div></div></section>';
  }
  function userGate(kind) {
    if (!state.session) return '<p class="gate">Pour ' + (kind === 'order' ? 'commander' : 'réserver') + ', <a href="/connexion">connectez-vous ou créez un compte</a>. Le numéro de téléphone est obligatoire.</p>';
    if (state.session.role === 'admin') return '<p class="gate">Vous êtes connecté en administrateur. <a href="/admin">Ouvrir le tableau de bord</a>.</p>';
    if (!state.session.verified) return '<p class="gate warning">Bonjour ' + esc(state.session.name) + '. Le restaurant doit d’abord valider votre compte avant de débloquer les créneaux.</p>';
    return '<p class="gate success">Bonjour ' + esc(state.session.name) + ', votre compte est vérifié : les créneaux disponibles sont prêts.</p>';
  }
  function orderSection() {
    const withSlugs = slugs => state.products.filter(product => slugs.includes(product.slug));
    const gourmand = state.products.find(product => product.slug === 'le-gourmand');
    const groups = [
      { id:'burgers', title:'Burgers maison', products:withSlugs(['le-p-tit-cheese','le-breton','le-chevre-miel','le-poulet-crudites','le-veg','burger-semaine']).concat(newProducts('BURGER')), burgerOptions:true },
      { id:'plats', title:'Les plats', products:withSlugs(['steak-hache-frites','filet-poulet-fermier','galette-legumes']) },
      { id:'formules', title:'Formules', products:withSlugs(['formule-burger-accompagnement']) },
      { id:'enfants', title:'Menu enfant', products:withSlugs(['kids-cheese-frites','kids-nuggets-frites']) },
      { id:'accompagnements', title:'Accompagnements & p’tits plus', products:state.products.filter(product => product.category === 'ACCOMPAGNEMENT' && product.slug !== 'le-gourmand') },
      { id:'desserts', title:'Desserts', products:state.products.filter(product => product.category === 'DESSERT') },
      { id:'chaudes', title:'Boissons chaudes', products:withSlugs(['cafe','double-cafe','the','infusion']) },
      { id:'softs', title:'Boissons soft', products:withSlugs(['eau-plate','eau-gazeuse','cola-artisanal','breizh-cola-zero','sirop-eau','jus-pommes','limonade-bretonne','the-glace-maison']).concat(newProducts('BOISSON')) },
      { id:'alcools', title:'Bières, cidre & vins', products:withSlugs(['digestif','biere-locale','cidre-local','vin-verre','vin-bouteille']) }
    ].filter(group => group.products.length);
    const selected = state.products.filter(product => product.slug !== 'le-gourmand' && state.basket[product.id]).map(product => ({ ...product, qty: state.basket[product.id] }));
    const gourmandCount = gourmand ? Object.keys(state.gourmandExtras).reduce((sum,id) => sum + (state.gourmandExtras[id] ? (state.basket[id] || 0) : 0), 0) : 0;
    const total = selected.reduce((sum, product) => sum + product.priceCents * product.qty, 0) + (gourmand?.priceCents || 0) * gourmandCount;
    const basketLabel = selected.length ? selected.map(product => product.qty + ' × ' + esc(product.name)).concat(gourmandCount ? [gourmandCount + ' × Supplément Gourmand'] : []).join('<br>') : 'Ajoutez un produit';
    const productCard = (product, burgerOptions) => '<article class="product"><div><h4>'+esc(product.name)+(burgerOptions?'<sup aria-label="Option Gourmand disponible">*</sup>':'')+'</h4><p>'+esc(product.description)+'</p><strong>'+money(product.priceCents)+'</strong>'+(burgerOptions&&gourmand?'<label class="gourmandChoice"><input type="checkbox" data-gourmand-option="'+product.id+'" '+(state.gourmandExtras[product.id]?'checked ':'')+(!state.basket[product.id]?'disabled ':'')+'><span>Option Gourmand <b>+'+money(gourmand.priceCents)+'</b></span></label>':'')+'</div><div class="stepper"><button aria-label="Retirer '+esc(product.name)+'" data-product-minus="'+product.id+'">−</button><b>'+(state.basket[product.id]||0)+'</b><button aria-label="Ajouter '+esc(product.name)+'" data-product-plus="'+product.id+'">+</button></div></article>';
    return '<section class="section order clickCollect" id="commander"><details class="commerceDisclosure orderDisclosure" data-disclosure="order" '+(state.orderOpen?'open':'')+'><summary><span><span class="eyebrow">Click & collect</span><strong>Composer ma commande</strong><small>Choisir mes produits et mon créneau de retrait</small></span><b aria-hidden="true">+</b></summary><div class="disclosureBody"><div class="section-heading"><h2>Composez votre commande, réglez au retrait.</h2><p>Aucun paiement en ligne. La commande est transmise au restaurant dès la validation du créneau.</p></div>'+userGate('order')+'<nav class="category-links" aria-label="Gammes de produits">'+groups.map(group=>'<button type="button" data-order-jump="gamme-'+group.id+'">'+esc(group.title)+'</button>').join('')+'</nav><div class="order-layout"><div class="catalog">'+groups.map((group,index)=>'<details class="product-group orderProductGroup" id="gamme-'+group.id+'" '+(index===0?'open':'')+'><summary><strong>'+esc(group.title)+'</strong><em>'+group.products.length+' choix</em><b aria-hidden="true">+</b></summary><div class="product-list">'+group.products.map(product=>productCard(product,group.burgerOptions)).join('')+'</div>'+(group.burgerOptions&&gourmand?'<p class="orderFootnote">* Option facultative : supplément de poulet ou de bœuf '+money(gourmand.priceCents)+'.</p>':'')+'</details>').join('')+'</div><form id="order-form" class="order-card"><p>Votre panier</p><h3>'+basketLabel+'</h3><div class="total"><span>Total à régler sur place</span><strong>'+money(total)+'</strong></div><label>Date de retrait<input required name="date" type="date" min="'+state.date+'" value="'+esc(state.orderDate||'')+'"></label><label>Créneau disponible<select required name="time"><option value="">Choisissez une date</option>'+state.slots.map(slot=>'<option value="'+slot.time+'" '+(!slot.available?'disabled':'')+'>'+slot.time+(!slot.available?' — complet':'')+'</option>').join('')+'</select></label><label>Une précision ?<textarea name="note" maxlength="300" placeholder="Ex. sans oignons"></textarea></label><button class="button" '+(!state.session?.verified||!selected.length?'disabled':'')+'>Commander et retirer</button><small>Le paiement se fait directement au restaurant.</small></form></div></div></details></section>';
  }
  function reservationSection() {
    return '<section class="section reservationPanel" id="reservation"><div class="reservationWrap"><details class="commerceDisclosure reservationDisclosure" data-disclosure="reservation" ' + (state.reservationOpen ? 'open' : '') + '><summary><span><span class="eyebrow">Réservation sur place</span><strong>Réserver une table</strong><small>Choisir votre date, votre créneau et le nombre de personnes</small></span><b aria-hidden="true">+</b></summary><div class="disclosureBody"><div class="reservation"><div class="section-heading"><p class="eyebrow">Réservation sur place</p><h2>Une table, un créneau clair.</h2><p>Les créneaux sont réglés par le restaurant : un créneau complet devient immédiatement indisponible.</p></div>' + userGate('reservation') + '<form id="reservation-form" class="booking-form"><label>Téléphone<input required name="phone" value="' + esc(state.session?.phone || '') + '" inputmode="tel" maxlength="24"></label><label>Nombre de personnes<input required name="guests" type="number" min="1" max="18" value="2"></label><label>Date<input required name="date" type="date" min="' + state.date + '" value="' + esc(state.reservationDate || '') + '"></label><label>Créneau<select required name="time"><option value="">Choisissez une date</option>' + state.reservationSlots.map(s => '<option value="' + s.time + '" ' + (!s.available ? 'disabled' : '') + '>' + s.time + (!s.available ? ' — déjà réservé' : '') + '</option>').join('') + '</select></label><label class="wide">Demande particulière<textarea name="note" maxlength="500" placeholder="Allergie, poussette, préférence de table…"></textarea></label><button class="button" ' + (!state.session?.verified ? 'disabled' : '') + '>Demander cette réservation</button></form></div></div></details></div></section>';
  }
  function restaurantSection() { const c = content(); return '<section class="section resto" id="resto"><div class="restoGallery"><figure class="restoFacade"><img src="/resto/facade-le-ptit-resto-29.jpg" alt="Façade du P’tit Resto 29 à Fouesnant" width="960" height="720" loading="lazy"><figcaption><span>Bienvenue chez nous</span><strong>5, rue de Kernévéleck · Fouesnant</strong></figcaption></figure><figure class="restoKitchen"><img src="/resto/en-cuisine.webp" alt="La cuisine du P’tit Resto 29" width="640" height="640" loading="lazy"><figcaption>En cuisine, chaque service se prépare sur place.</figcaption></figure></div><div class="restoStory"><p class="eyebrow">Le resto · depuis 2015</p><h2>Une maison de burgers, au cœur de Fouesnant.</h2><p class="restoLead">Ici, on cuisine des burgers et des frites maison avec des produits frais, choisis auprès de producteurs et d’éleveurs locaux.</p><p class="restoCopy">Sur place, l’ambiance est simple et conviviale : une table où l’on vient partager un bon moment, en famille ou entre amis. À emporter, la même cuisine généreuse vous accompagne à la maison, au bureau ou pour profiter du pays fouesnantais.</p><div class="restoValues" aria-label="Les engagements du restaurant"><article><strong>Fait maison</strong><span>Burgers et frites préparés avec soin.</span></article><article><strong>Produits frais</strong><span>Une cuisine franche, locale et gourmande.</span></article><article><strong>Sur place ou à emporter</strong><span>Le même goût, selon votre envie.</span></article></div><dl class="restoDetails"><div><dt>Adresse</dt><dd>' + esc(c.address) + '</dd></div><div><dt>Horaires</dt><dd>' + esc(c.openingHours) + '</dd></div><div><dt>Réserver ou commander</dt><dd><a href="tel:' + esc((c.phone || '').replace(/\s/g, '')) + '">' + esc(c.phone) + '</a></dd></div></dl></div></section>'; }
  function loginPage() { return pageShell('<main class="auth-page"><section class="auth-intro"><p class="eyebrow">Un accès unique</p><h1>Votre espace s’ouvre automatiquement.</h1><p>Un client rejoint la carte, ses réservations et ses commandes. L’administrateur est dirigé vers la gestion du restaurant.</p><ul><li>Téléphone obligatoire pour les comptes clients</li><li>Réservations et retraits réservés aux comptes validés</li><li>Aucun paiement en ligne</li></ul></section><section class="auth-card"><div class="auth-tabs"><button data-auth-tab="login" class="active">Connexion</button><button data-auth-tab="register">Créer un compte</button></div><form id="login-form"><label>Adresse e-mail<input required name="email" type="email" autocomplete="email"></label><label>Mot de passe<input required name="password" type="password" autocomplete="current-password"></label><button class="button">Se connecter</button></form><form id="register-form" hidden><label>Prénom et nom<input required name="name" minlength="2" maxlength="80" autocomplete="name"></label><label>Numéro de téléphone<input required name="phone" type="tel" minlength="8" maxlength="24" autocomplete="tel"></label><label>Adresse e-mail<input required name="email" type="email" autocomplete="email"></label><label>Mot de passe<input required name="password" type="password" minlength="10" maxlength="128" autocomplete="new-password"></label><button class="button">Créer mon compte</button><small>Votre compte sera validé par le restaurant avant de réserver ou commander.</small></form></section></main>'); }
  function account() {
    if (!state.session) return pageShell('<main class="empty-page"><h1>Retrouvez vos commandes et réservations.</h1><a class="button" href="/connexion">Se connecter</a></main>');
    if (state.session.role === 'admin') { window.location.replace('/admin'); return ''; }
    const history = state.history || { reservations: [], orders: [] };
    return pageShell('<main class="account-page"><section class="account-hero"><div><p class="eyebrow">Espace client · ' + esc(state.session.name) + '</p><h1>Vos commandes, réservations et fidélité.</h1><p>' + (state.session.verified ? 'Votre compte est vérifié : vous pouvez réserver une table ou commander à emporter.' : 'Votre compte est en attente de validation par le restaurant.') + '</p></div><button class="quiet-button" data-action="logout">Déconnexion</button></section><section class="stats"><article><span>Statut</span><strong class="' + (state.session.verified ? 'ok' : 'pending') + '">' + (state.session.verified ? 'Compte vérifié' : 'À valider') + '</strong></article><article><span>Fidélité</span><strong>' + state.session.loyaltyPoints + ' pts</strong></article><article><span>Téléphone</span><strong>' + esc(state.session.phone) + '</strong></article></section><div class="history-columns"><section><div class="section-heading compact"><p class="eyebrow">Sur place</p><h2>Mes réservations</h2></div>' + (history.reservations.length ? history.reservations.map(r => '<article class="history-card"><strong>' + dateLabel(r.date, r.time) + '</strong><span>' + r.guests + ' personne' + (r.guests > 1 ? 's' : '') + ' · ' + esc(statusLabel(r.status)) + '</span>' + (r.note ? '<p>' + esc(r.note) + '</p>' : '') + '</article>').join('') : '<p class="empty">Aucune réservation pour le moment.</p>') + '<a class="text-link" href="/#reservation">Réserver une table →</a></section><section><div class="section-heading compact"><p class="eyebrow">Click & collect</p><h2>Mes commandes</h2></div>' + (history.orders.length ? history.orders.map(o => '<article class="history-card"><strong>Retrait le ' + dateLabel(o.date, o.time) + '</strong><span>' + esc(statusLabel(o.status)) + ' · ' + money(o.subtotalCents) + '</span><p>' + o.items.map(i => i.quantity + ' × ' + esc(i.productName)).join(' · ') + '</p></article>').join('') : '<p class="empty">Aucune commande pour le moment.</p>') + '<a class="text-link" href="/#commander">Préparer une commande →</a></section></div></main>');
  }
  function admin() {
    if (!state.session || state.session.role !== 'admin') return pageShell('<main class="empty-page"><h1>Administration réservée.</h1><a class="button" href="/connexion">Se connecter</a></main>');
    const data = state.overview || { reservations: [], orders: [], customers: [], settings: {} }; const config = data.settings || {};
    const periodTitle = state.period === 'week' ? 'La semaine' : state.period === 'month' ? 'Le mois' : 'La journée';
    const inclusiveEnd = data.end ? new Date(data.end + 'T12:00:00Z') : null; if (inclusiveEnd) inclusiveEnd.setUTCDate(inclusiveEnd.getUTCDate() - 1);
    const periodRange = data.start && inclusiveEnd ? (state.period === 'day' ? dateLabel(data.start) : 'Du ' + dateLabel(data.start) + ' au ' + dateLabel(inclusiveEnd.toISOString().slice(0,10))) : 'Chargement de la période…';
    const productGroups = Object.entries(categoryNames).map(([category,title]) => ({ category, title, products: state.products.filter(product => product.category === category) })).filter(group => group.products.length);
    const productAdminList = '<div class="adminProductGroups">' + productGroups.map((group,index) => '<details class="adminProductGroup" '+(index===0?'open':'')+'><summary><span><small>Catégorie</small><strong>'+esc(group.title)+'</strong></span><em>'+group.products.length+' produit'+(group.products.length>1?'s':'')+'</em><b aria-hidden="true">+</b></summary><div class="adminProductGrid">'+group.products.map(p => '<article class="adminProductCard"><div><span class="adminProductStatus '+(p.available?'available':'unavailable')+'">'+(p.available?'Disponible':'Masqué')+'</span><h3>'+esc(p.name)+'</h3><p>'+esc(p.description)+'</p></div><div class="adminProductActions"><strong>'+money(p.priceCents)+'</strong><span><button class="small-button" data-edit-product="'+p.id+'">Modifier</button><button class="delete-button" data-delete-product="'+p.id+'">Supprimer</button></span></div></article>').join('')+'</div></details>').join('') + '</div>';
    return pageShell('<main class="admin-page"><section class="admin-top"><div><p class="eyebrow">Gestion du restaurant</p><h1>' + periodTitle + ' en un coup d’œil.</h1><p>Réservations sur place, retraits, clients et contenu du site sont regroupés ici.</p></div><a class="button outline" href="/">← Retour à l’accueil</a></section><nav class="admin-nav"><a href="/admin">Réservations et commandes</a><a href="/admin/contenu">Contenu, produits et photos</a></nav><section class="period-bar"><div><button data-period="day" aria-pressed="' + (state.period === 'day') + '" class="' + (state.period === 'day' ? 'selected' : '') + '">Journée</button><button data-period="week" aria-pressed="' + (state.period === 'week') + '" class="' + (state.period === 'week' ? 'selected' : '') + '">Semaine</button><button data-period="month" aria-pressed="' + (state.period === 'month') + '" class="' + (state.period === 'month' ? 'selected' : '') + '">Mois</button></div><strong class="periodRange">' + esc(periodRange) + '</strong><label>Date de référence <input id="admin-date" type="date" value="' + esc(state.date) + '"></label></section><section class="admin-summary"><article title="Chaque demande apparaît avec son créneau, le nombre de personnes et les coordonnées du client."><span>Réservations</span><strong>' + data.reservations.length + '</strong><small>dans la période choisie</small></article><article title="Les commandes affichent le créneau de retrait, leur contenu et leur état de préparation."><span>Retraits</span><strong>' + data.orders.length + '</strong><small>à préparer ou suivre</small></article><article title="Les comptes non validés ne peuvent pas réserver ni commander. Validez-les plus bas."><span>Clients à valider</span><strong>' + data.customers.filter(c => !c.verified).length + '</strong><small>accès bloqué</small></article></section><section class="admin-grid"><article class="admin-panel wide"><div class="panel-heading"><div><p class="eyebrow">Sur place</p><h2>Réservations</h2><p>Les créneaux complets sont bloqués automatiquement.</p></div></div>' + (data.reservations.length ? '<div class="data-list">' + data.reservations.map(r => '<details open><summary><strong>' + dateLabel(r.date, r.time) + '</strong><span>' + esc(r.name) + ' · ' + r.guests + ' pers.</span><b>' + esc(statusLabel(r.status)) + '</b></summary><p><b>Téléphone :</b> ' + esc(r.phone) + '<br><b>E-mail :</b> ' + esc(r.email) + (r.note ? '<br><b>Note :</b> ' + esc(r.note) : '') + '</p>' + statusControl('reservations',r) + '</details>').join('') + '</div>' : '<p class="empty">Aucune réservation sur cette période.</p>') + '</article><article class="admin-panel wide"><div class="panel-heading"><div><p class="eyebrow">Click & collect</p><h2>Commandes à retirer</h2><p>Le contenu de chaque commande est visible sans changer de page.</p></div></div>' + (data.orders.length ? '<div class="data-list">' + data.orders.map(o => '<details open><summary><strong>' + dateLabel(o.date, o.time) + '</strong><span>' + esc(o.name) + ' · ' + money(o.subtotalCents) + '</span><b>' + esc(statusLabel(o.status)) + '</b></summary><p><b>Articles :</b> ' + o.items.map(i => i.quantity + ' × ' + esc(i.productName)).join(' · ') + '<br><b>Client :</b> ' + esc(o.email) + (o.note ? '<br><b>Note :</b> ' + esc(o.note) : '') + '<br><b>Téléphone :</b> '+esc(o.phone)+'</p>' + statusControl('orders',o) + '</details>').join('') + '</div>' : '<p class="empty">Aucune commande sur cette période.</p>') + '</article><article class="admin-panel"><div class="panel-heading"><div><p class="eyebrow">Comptes clients</p><h2>Validation</h2><p>Un clic débloque ou rebloque les réservations et commandes.</p></div></div><div class="customer-list">' + data.customers.map(c => '<div><span><strong>' + esc(c.name) + '</strong><small>' + esc(c.email) + '<br>' + esc(c.phone) + '</small></span><button class="small-button ' + (c.verified ? 'verified' : '') + '" data-customer="' + c.id + '" data-verified="' + (!c.verified) + '">' + (c.verified ? 'Validé' : 'Valider') + '</button></div>').join('') + '</div></article><article class="admin-panel"><div class="panel-heading"><div><p class="eyebrow">Créneaux</p><h2>Règles de disponibilité</h2><p>Les limites s’appliquent immédiatement aux futurs créneaux.</p></div></div><form id="settings-form" class="admin-form"><label>Intervalle<select name="slotIntervalMinutes"><option value="5" ' + (config.slotIntervalMinutes === 5 ? 'selected' : '') + '>5 minutes</option><option value="10" ' + (config.slotIntervalMinutes === 10 ? 'selected' : '') + '>10 minutes</option><option value="15" ' + (config.slotIntervalMinutes === 15 ? 'selected' : '') + '>15 minutes</option><option value="20" ' + (config.slotIntervalMinutes === 20 ? 'selected' : '') + '>20 minutes</option><option value="30" ' + (config.slotIntervalMinutes === 30 ? 'selected' : '') + '>30 minutes</option></select></label><label>Réservations / créneau<input name="reservationCapacity" type="number" min="1" max="30" value="' + esc(config.reservationCapacity || 1) + '"></label><label>Retraits / créneau<input name="pickupCapacity" type="number" min="1" max="80" value="' + esc(config.pickupCapacity || 5) + '"></label><label>Midi début<input name="lunchStartMinutes" type="time" required value="' + clockValue(config.lunchStartMinutes ?? 720) + '"></label><label>Midi fin<input name="lunchEndMinutes" type="time" required value="' + clockValue(config.lunchEndMinutes ?? 810) + '"></label><label>Soir début<input name="dinnerStartMinutes" type="time" required value="' + clockValue(config.dinnerStartMinutes ?? 1140) + '"></label><label>Soir fin<input name="dinnerEndMinutes" type="time" required value="' + clockValue(config.dinnerEndMinutes ?? 1260) + '"></label><fieldset><legend>Jours ouverts</legend>' + [['0','Dim'],['1','Lun'],['2','Mar'],['3','Mer'],['4','Jeu'],['5','Ven'],['6','Sam']].map(([v,l]) => '<label class="check"><input name="weekdays" type="checkbox" value="' + v + '" ' + (config.openWeekdays?.includes(Number(v)) ? 'checked' : '') + '>' + l + '</label>').join('') + '</fieldset><button class="small-button">Enregistrer les créneaux</button></form></article><article class="admin-panel wide productManagement"><div class="panel-heading"><div><p class="eyebrow">La carte</p><h2>Produits</h2><p>Ajoutez un produit ou supprimez les recettes qui ne sont plus proposées.</p></div></div><form id="product-form" class="admin-form"><label>Nom<input name="name" required maxlength="100"></label><label>Catégorie<select name="category"><option>BURGER</option><option>ACCOMPAGNEMENT</option><option>BOISSON</option><option>DESSERT</option></select></label><label>Prix (€)<input name="priceEuros" required type="number" step="0.01" min="0" max="1000"></label><label>Description<textarea name="description" required maxlength="350"></textarea></label><label class="check"><input name="available" type="checkbox" checked>Disponible à la commande</label><button class="small-button">Ajouter le produit</button></form>' + productAdminList + '</article><article class="admin-panel"><div class="panel-heading"><div><p class="eyebrow">Contenu public</p><h2>Informations du site</h2><p>Les textes ci-dessous s’affichent immédiatement sur la page d’accueil.</p></div></div><form id="content-form" class="admin-form"><label>Nom du restaurant<input name="restaurantName" required value="' + esc(content().restaurantName) + '"></label><label>Ville<input name="town" required value="' + esc(content().town) + '"></label><label>Adresse<input name="address" required value="' + esc(content().address) + '"></label><label>Téléphone<input name="phone" required value="' + esc(content().phone) + '"></label><label>Horaires<input name="openingHours" required value="' + esc(content().openingHours) + '"></label><label>Surtitre<input name="heroEyebrow" required value="' + esc(content().heroEyebrow) + '"></label><label>Titre<input name="heroTitle" required value="' + esc(content().heroTitle) + '"></label><label>Texte<textarea name="heroText" required maxlength="500">' + esc(content().heroText) + '</textarea></label><button class="small-button">Mettre à jour le site</button></form></article><article class="admin-panel wide"><div class="panel-heading"><div><p class="eyebrow">Carrousel</p><h2>Photos de la semaine</h2><p>Ajoutez une image, modifiez son ordre ou supprimez-la. Les photos sont stockées avec le site.</p></div></div><form id="slide-form" class="upload-form"><label>Titre<input name="title" required maxlength="100" placeholder="Ex. Le double bacon"></label><label class="dropzone">Glissez une photo ici ou choisissez un fichier (4 Mo maximum)<input name="image" required type="file" accept="image/png,image/jpeg,image/webp"></label><button class="small-button">Ajouter au carrousel</button></form><div class="slide-admin-list">' + state.slides.map((s, i) => '<article><div class="slide-thumb" style="background-image:url(\'' + esc(safeUrl(s.image)) + '\')"></div><div><strong>' + esc(s.title) + '</strong><small>Position ' + (i + 1) + '</small></div><div class="slide-actions"><button class="small-button" data-slide-order="' + s.id + '" data-order="' + (s.sortOrder - 10) + '">↑</button><button class="small-button" data-slide-order="' + s.id + '" data-order="' + (s.sortOrder + 10) + '">↓</button><button class="delete-button" data-delete-slide="' + s.id + '">Supprimer</button></div></article>').join('') + '</div></article></section></main>');
  }
  function render() {
    // Seuls les formulaires réellement modifiés conservent leur saisie : sinon, des valeurs par défaut
    // affichées avant le chargement écrasaient les vrais réglages (ex. créneaux de l'administration).
    const drafts = [...document.querySelectorAll('form[id]')].filter(form => form.dataset.dirty === 'true').map(form => ({ id:form.id, values:[...form.elements].filter(el=>el.name && el.type!=='file' && el.type!=='password').map(el=>({name:el.name,value:el.value,checked:el.checked,type:el.type})) }));
    const focused=document.activeElement, focusName=focused?.name, focusForm=focused?.form?.id;
    const path = location.pathname; $('#app').innerHTML = path === '/connexion' ? loginPage() : path === '/compte' ? account() : path.startsWith('/admin') ? admin() : home(); bind(); updateCarousel();
    if(path.startsWith('/admin')&&state.session?.role==='admin'){
      const contentRoute=path==='/admin/contenu';
      document.querySelectorAll('.admin-grid>.admin-panel').forEach((panel,i)=>{panel.hidden=contentRoute?i<4:i>=4;});
      document.querySelectorAll('.period-bar,.admin-summary').forEach(el=>el.hidden=contentRoute);
      if(contentRoute){$('.admin-top h1').textContent='Le contenu de votre restaurant.';$('.admin-top p:last-child').textContent='Votre carte, vos textes et les photos du carrousel.';}
    }
    drafts.forEach(draft=>{ const form=document.getElementById(draft.id); if (!form) return; form.dataset.dirty='true'; draft.values.forEach(v=>{ const elements=[...form.elements].filter(el=>el.name===v.name); for(const el of elements){if(v.type==='checkbox'||v.type==='radio'){if(el.value===v.value)el.checked=v.checked;}else if(v.name!=='date'||!form.id.includes('admin')){el.value=v.value;}} }); });
    if(focusName && focusForm) document.getElementById(focusForm)?.querySelector('[name="'+focusName+'"]')?.focus({preventScroll:true});
  }
  function bind() {
    document.querySelectorAll('form[id]').forEach(form=>['input','change'].forEach(type=>form.addEventListener(type,()=>{form.dataset.dirty='true';})));
    document.querySelectorAll('form[id]').forEach(form=>form.addEventListener('reset',()=>{delete form.dataset.dirty;}));
    document.querySelectorAll('.headerMenu').forEach(menu=>menu.addEventListener('toggle',()=>{
      if(menu.open)document.querySelectorAll('.headerMenu').forEach(other=>{if(other!==menu)other.open=false;});
    }));
    document.querySelectorAll('[data-status-id]').forEach(el=>el.addEventListener('change',async()=>{
      const value=el.value;
      let reason='';
      if(value==='CANCELLED'&&el.dataset.statusKind==='reservations'){
        if(!confirm('Refuser cette réservation et libérer le créneau ?')){loadAdmin();return;}
        reason=(prompt('Motif communiqué au client :','')||'').trim();
        if(reason.length<3){loadAdmin();flash('Indiquez un motif clair pour prévenir le client.','error');return;}
      }else if(['CANCELLED','COLLECTED'].includes(value)&&!confirm(value==='CANCELLED'?'Annuler cette demande et libérer le créneau ?':'Confirmer le retrait et le paiement sur place ?')){loadAdmin();return;}
      el.disabled=true;
      try{const result=await api('/api/admin/'+el.dataset.statusKind+'/'+el.dataset.statusId,{method:'PATCH',body:{status:value,...(reason?{reason}: {})}});await loadAdmin();flash('Statut mis à jour.'+(result.notification?.sent?' Le client a été prévenu par e-mail.':''));}catch(e){await loadAdmin();flash(e.message,'error');}
    }));
    document.querySelectorAll('form').forEach(form=>form.addEventListener('submit',event=>{
      if(form.dataset.pending==='true'){event.preventDefault();event.stopImmediatePropagation();return;}
      form.dataset.pending='true';form.querySelectorAll('button[type="submit"],button:not([type])').forEach(btn=>btn.disabled=true);
    },true));
    document.querySelectorAll('[data-edit-product]').forEach(el=>el.addEventListener('click',()=>{
      const product=state.products.find(p=>p.id===el.dataset.editProduct),form=$('#product-form'); if(!product||!form)return;
      state.editingProduct=product.id; ['name','category','description'].forEach(key=>form.elements[key].value=product[key]);form.elements.priceEuros.value=(product.priceCents/100).toFixed(2);
      form.elements.available.checked=product.available;form.querySelector('button').textContent='Enregistrer le produit';form.scrollIntoView({behavior:'smooth',block:'center'});
    }));
    const drop=$('.dropzone');
    if(drop){['dragenter','dragover'].forEach(name=>drop.addEventListener(name,event=>{event.preventDefault();drop.classList.add('dragover');}));drop.addEventListener('dragleave',()=>drop.classList.remove('dragover'));drop.addEventListener('drop',event=>{event.preventDefault();drop.classList.remove('dragover');if(event.dataTransfer.files.length)drop.querySelector('input[type=file]').files=event.dataTransfer.files;});}
    document.querySelectorAll('[data-disclosure]').forEach(panel => panel.addEventListener('toggle', () => { state[panel.dataset.disclosure + 'Open'] = panel.open; }));
    document.querySelectorAll('[data-menu-jump]').forEach(button => button.addEventListener('click', () => {
      const target = document.getElementById(button.dataset.menuJump); if (!target) return;
      document.querySelectorAll('.menuGroup').forEach(group => { group.open = group === target; });
      requestAnimationFrame(() => target.scrollIntoView({ behavior:'smooth', block:'start' }));
    }));
    document.querySelectorAll('.menuGroup').forEach(group => group.addEventListener('toggle', () => { if (group.open) document.querySelectorAll('.menuGroup').forEach(other => { if (other !== group) other.open=false; }); }));
    document.querySelectorAll('[data-order-jump]').forEach(button => button.addEventListener('click', () => {
      const target = document.getElementById(button.dataset.orderJump); if (!target) return;
      document.querySelectorAll('.orderProductGroup').forEach(group => { group.open = group === target; });
      requestAnimationFrame(() => target.scrollIntoView({ behavior:'smooth', block:'start' }));
    }));
    document.querySelectorAll('.orderProductGroup').forEach(group => group.addEventListener('toggle', () => { if (group.open) document.querySelectorAll('.orderProductGroup').forEach(other => { if (other !== group) other.open=false; }); }));

    document.querySelectorAll('[data-slide]').forEach(el => el.addEventListener('click', () => { state.carouselIndex = Number(el.dataset.slide); updateCarousel(); }));
    $('[data-action="carousel-prev"]')?.addEventListener('click', () => { state.carouselIndex = (state.carouselIndex - 1 + state.slides.length) % Math.max(1,state.slides.length); updateCarousel(); });
    $('[data-action="carousel-next"]')?.addEventListener('click', () => { state.carouselIndex = (state.carouselIndex + 1) % Math.max(1,state.slides.length); updateCarousel(); });
    document.querySelectorAll('[data-product-plus]').forEach(el => el.addEventListener('click', () => { const id = el.dataset.productPlus; state.basket[id] = Math.min(12, (state.basket[id] || 0) + 1); render(); }));
    document.querySelectorAll('[data-product-minus]').forEach(el => el.addEventListener('click', () => { const id = el.dataset.productMinus; state.basket[id] = Math.max(0, (state.basket[id] || 0) - 1); if (!state.basket[id]) { delete state.basket[id]; delete state.gourmandExtras[id]; } render(); }));
    document.querySelectorAll('[data-gourmand-option]').forEach(el => el.addEventListener('change', () => { state.gourmandExtras[el.dataset.gourmandOption] = el.checked; render(); }));
    document.querySelectorAll('[data-action="logout"]').forEach(el => el.addEventListener('click', logout));
    document.querySelectorAll('[data-auth-tab]').forEach(el => el.addEventListener('click', () => { const register = el.dataset.authTab === 'register'; $('#login-form').hidden = register; $('#register-form').hidden = !register; document.querySelectorAll('[data-auth-tab]').forEach(btn => btn.classList.toggle('active', btn === el)); }));
    $('#order-form')?.addEventListener('submit', order);
    $('#reservation-form')?.addEventListener('submit', reservation);
    $('#order-form [name="date"]')?.addEventListener('change', event => loadSlots('pickup', event.target.value));
    $('#reservation-form [name="date"]')?.addEventListener('change', event => loadSlots('reservation', event.target.value));
    $('#login-form')?.addEventListener('submit', login);
    $('#register-form')?.addEventListener('submit', register);
    document.querySelectorAll('[data-period]').forEach(el => el.addEventListener('click', () => { state.period = el.dataset.period; loadAdmin(); }));
    $('#admin-date')?.addEventListener('change', event => { state.date = event.target.value; loadAdmin(); });
    document.querySelectorAll('[data-customer]').forEach(el => el.addEventListener('click', async () => { try { await api('/api/admin/customers/' + el.dataset.customer, { method: 'PATCH', body: { verified: el.dataset.verified === 'true' } }); await loadAdmin(); flash('Statut du compte mis à jour.'); } catch (e) { flash(e.message, 'error'); } }));
    $('#settings-form')?.addEventListener('submit', saveSettings);
    $('#product-form')?.addEventListener('submit', addProduct);
    document.querySelectorAll('[data-delete-product]').forEach(el => el.addEventListener('click', () => deleteProduct(el.dataset.deleteProduct)));
    $('#content-form')?.addEventListener('submit', saveContent);
    $('#slide-form')?.addEventListener('submit', addSlide);
    document.querySelectorAll('[data-delete-slide]').forEach(el => el.addEventListener('click', () => deleteSlide(el.dataset.deleteSlide)));
    document.querySelectorAll('[data-slide-order]').forEach(el => el.addEventListener('click', () => orderSlide(el.dataset.slideOrder, el.dataset.order)));
  }
  async function login(event) { event.preventDefault(); try { const form = new FormData(event.currentTarget); const result = await api('/api/auth/login', { method: 'POST', body: Object.fromEntries(form) }); if (API_BASE && result.sessionToken) localStorage.setItem(SESSION_STORAGE_KEY, result.sessionToken); state.session = result.user; location.assign(result.redirect); } catch (e) { flash(e.message, 'error'); } }
  async function register(event) { event.preventDefault(); try { const result = await api('/api/auth/register', { method: 'POST', body: Object.fromEntries(new FormData(event.currentTarget)) }); if (API_BASE && result.sessionToken) localStorage.setItem(SESSION_STORAGE_KEY, result.sessionToken); state.session = result.user; location.assign('/'); } catch (e) { flash(e.message, 'error'); } }
  async function logout() { try { await api('/api/auth/logout', { method: 'POST' }); if (API_BASE) localStorage.removeItem(SESSION_STORAGE_KEY); state.session = null; state.history = null; location.assign('/connexion'); } catch (e) { flash(e.message, 'error'); } }
  async function loadSlots(kind, date) {
    const form = document.getElementById(kind==='pickup'?'order-form':'reservation-form'), select = form?.elements.time;
    if (select) {select.innerHTML='<option value="">Chargement…</option>';select.disabled=true;}
    if (!date || !state.session?.verified || state.session.role!=='customer') {if(select)select.innerHTML='<option value="">Connectez-vous avec un compte client vérifié</option>';return;}
    try { const result = await api('/api/slots?kind=' + kind + '&date=' + encodeURIComponent(date)); if (kind === 'pickup') { state.orderDate = date; state.slots = result.slots; } else { state.reservationDate = date; state.reservationSlots = result.slots; }
    if(form?.elements.date.value===date && select){select.disabled=false;select.innerHTML='<option value="">' + (result.slots.some(s=>s.available)?'Choisissez un créneau':'Aucun créneau disponible ce jour') + '</option>' + result.slots.map(s=>'<option value="'+s.time+'" '+(!s.available?'disabled':'')+'>'+s.time+(!s.available?' — complet':'')+'</option>');}
    } catch (e) { if(select){select.innerHTML='<option value="">Créneaux indisponibles</option>';select.disabled=true;}flash(e.message, 'error'); } }
  async function order(event) { event.preventDefault(); if (!state.session?.verified) return flash('Votre compte doit être validé par le restaurant.', 'error'); try { const form = new FormData(event.currentTarget); const gourmand = state.products.find(product => product.slug === 'le-gourmand'); const items = Object.entries(state.basket).filter(([id]) => state.products.find(product => product.id === id)?.slug !== 'le-gourmand').map(([productId, quantity]) => ({ productId, quantity })); const gourmandCount = gourmand ? Object.keys(state.gourmandExtras).reduce((sum,id) => sum + (state.gourmandExtras[id] ? (state.basket[id] || 0) : 0), 0) : 0; if (gourmandCount) items.push({ productId:gourmand.id, quantity:gourmandCount }); const result = await api('/api/orders', { method: 'POST', body: { date: form.get('date'), time: form.get('time'), note: form.get('note'), items } }); state.basket = {}; state.gourmandExtras = {}; state.orderDate = ''; state.slots = []; document.getElementById('order-form')?.reset(); flash('Commande reçue : retrait prévu le ' + dateLabel(result.order.date, result.order.time) + '. Paiement sur place.'); refreshHome(); } catch (e) { flash(e.message, 'error'); } }
  async function reservation(event) { event.preventDefault(); if (!state.session?.verified) return flash('Votre compte doit être validé par le restaurant.', 'error'); try { const data = Object.fromEntries(new FormData(event.currentTarget)); const result = await api('/api/reservations', { method: 'POST', body: data }); state.reservationDate = ''; state.reservationSlots = []; document.getElementById('reservation-form')?.reset(); flash('Réservation confirmée pour le ' + dateLabel(result.reservation.date, result.reservation.time) + '.' + (result.notification?.sent ? ' Un e-mail de confirmation vous a été envoyé.' : '')); refreshHome(); } catch (e) { flash(e.message, 'error'); } }
  async function loadAdmin() {
    const token = ++state.adminLoadToken;
    try {
      const overview = await api('/api/admin/overview?period=' + state.period + '&date=' + state.date);
      if (token !== state.adminLoadToken) return;
      state.overview = overview;
      render();
    } catch (e) {
      if (token === state.adminLoadToken) flash(e.message, 'error');
    }
  }
  async function saveSettings(event) { event.preventDefault(); try { const form = new FormData(event.currentTarget); const body = Object.fromEntries(form); body.openWeekdays = form.getAll('weekdays').map(Number); ['slotIntervalMinutes','reservationCapacity','pickupCapacity','lunchStartMinutes','lunchEndMinutes','dinnerStartMinutes','dinnerEndMinutes'].forEach(key => body[key] = key.endsWith('Minutes') && key!=='slotIntervalMinutes' ? Number(body[key].split(':')[0])*60+Number(body[key].split(':')[1]) : Number(body[key])); await api('/api/admin/settings', { method: 'PATCH', body }); await loadAdmin(); flash('Créneaux mis à jour.'); } catch (e) { flash(e.message, 'error'); } }
  async function addProduct(event) { event.preventDefault(); try { const body = Object.fromEntries(new FormData(event.currentTarget)); body.priceCents = Math.round(Number(body.priceEuros)*100);body.available=new FormData(event.currentTarget).has('available');const editing=state.editingProduct;await api('/api/admin/products'+(editing?'/'+editing:''),{method:editing?'PATCH':'POST',body});state.editingProduct=null; document.getElementById('product-form')?.reset(); await refreshHome(); await loadAdmin(); flash('Produit enregistré dans la carte.'); } catch (e) { flash(e.message, 'error'); } }
  async function deleteProduct(id) { if (!confirm('Supprimer ce produit de la carte ?')) return; try { await api('/api/admin/products/' + id, { method: 'DELETE' }); await refreshHome(); await loadAdmin(); flash('Produit supprimé.'); } catch (e) { flash(e.message, 'error'); } }
  async function saveContent(event) { event.preventDefault(); try { await api('/api/admin/content', { method: 'PATCH', body: Object.fromEntries(new FormData(event.currentTarget)) }); await refreshHome(); await loadAdmin(); flash('Contenu du site mis à jour.'); } catch (e) { flash(e.message, 'error'); } }
  async function addSlide(event) { event.preventDefault(); try { await api('/api/admin/carousel', { method: 'POST', body: new FormData(event.currentTarget) }); await refreshHome(); await loadAdmin(); flash('Photo ajoutée au carrousel.'); } catch (e) { flash(e.message, 'error'); } }
  async function deleteSlide(id) { if (!confirm('Supprimer cette photo du carrousel ?')) return; try { await api('/api/admin/carousel/' + id, { method: 'DELETE' }); await refreshHome(); await loadAdmin(); flash('Photo supprimée.'); } catch (e) { flash(e.message, 'error'); } }
  async function orderSlide(id, order) { try { await api('/api/admin/carousel/' + id, { method: 'PATCH', body: { sortOrder: Number(order) } }); await refreshHome(); await loadAdmin(); } catch (e) { flash(e.message, 'error'); } }
  async function refreshHome() { const [contentData, catalogData, sessionData] = await Promise.all([api('/api/content'), api('/api/catalog'), api('/api/session')]); state.content = contentData.content; state.slides = contentData.slides; state.carouselIndex=Math.min(state.carouselIndex,Math.max(0,state.slides.length-1)); state.session = sessionData.user; if (API_BASE && !state.session) localStorage.removeItem(SESSION_STORAGE_KEY); state.products = state.session?.role==='admin' ? (await api('/api/admin/products')).products : catalogData.products; render(); }
  async function boot() { try { await refreshHome(); if (location.pathname === '/compte' && state.session?.role === 'customer') state.history = await api('/api/me/history'); if (location.pathname.startsWith('/admin') && state.session?.role === 'admin') state.overview = await api('/api/admin/overview?period=' + state.period + '&date=' + state.date); render(); } catch (e) { $('#app').innerHTML = '<main class="empty-page"><h1>Le site démarre.</h1><p>Vérifiez votre connexion puis rechargez la page.</p><button class="button" data-action="reload">Réessayer</button></main>'; $('[data-action="reload"]')?.addEventListener('click', () => location.reload()); } }
  document.addEventListener('click', (event) => { const link = event.target.closest('a[href^="/#"]'); if (link && location.pathname === '/') { event.preventDefault(); document.querySelector(link.getAttribute('href').slice(1))?.scrollIntoView({ behavior: 'smooth' }); } });
  window.setInterval(() => { if (location.pathname === '/' && state.slides.length > 1 && !document.hidden && !matchMedia('(prefers-reduced-motion: reduce)').matches && !$('.burgerCarousel')?.matches(':hover')) { state.carouselIndex = (state.carouselIndex + 1) % Math.max(1,state.slides.length); updateCarousel(); } }, 6500);
  boot();
})();
